-- Keep meaning-based links only. Back up exact removals for restoration.
CREATE TABLE IF NOT EXISTS idiom_revision_backup (revision TEXT NOT NULL, object_key TEXT NOT NULL, snapshot TEXT NOT NULL, PRIMARY KEY(revision,object_key));
CREATE TABLE idiom_ref_cleanup_0042 (idiom_id TEXT, phrase TEXT, sense_id TEXT, meaning TEXT, word_id TEXT, source TEXT);
-- Freeze only unchanged references in this notebook; concurrent edits survive.
DELETE FROM idiom_ref_cleanup_0042 WHERE NOT EXISTS (
 SELECT 1 FROM idiom_word_refs r JOIN idiom_senses s ON s.id=r.sense_id JOIN idioms i ON i.id=s.idiom_id
 WHERE i.list_id='crossover-v3' AND i.id=idiom_ref_cleanup_0042.idiom_id AND i.phrase=idiom_ref_cleanup_0042.phrase
 AND s.id=idiom_ref_cleanup_0042.sense_id AND s.meaning=idiom_ref_cleanup_0042.meaning
 AND r.word_id=idiom_ref_cleanup_0042.word_id AND r.source=idiom_ref_cleanup_0042.source
);
INSERT OR IGNORE INTO idiom_revision_backup (revision,object_key,snapshot)
SELECT '0042',sense_id || '/' || word_id,json_object('idiomId',idiom_id,'phrase',phrase,'senseId',sense_id,'meaning',meaning,'wordId',word_id,'source',source)
FROM idiom_ref_cleanup_0042;
DELETE FROM idiom_word_refs WHERE EXISTS (
 SELECT 1 FROM idiom_ref_cleanup_0042 t WHERE t.sense_id=idiom_word_refs.sense_id AND t.word_id=idiom_word_refs.word_id AND t.source=idiom_word_refs.source
);
DROP TABLE idiom_ref_cleanup_0042;
